<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {getStudio,type StudioPayload} from './content-studio-api';import {getVisitorState,type VPayload} from './visitor-content-api';const studio=ref<StudioPayload|null>(null),visitor=ref<VPayload|null>(null),message=ref(''),busy=ref(false);async function load(){[studio.value,visitor.value]=await Promise.all([getStudio(),getVisitorState()])}onMounted(load);const missing=computed(()=>Object.values(studio.value?.document.places||{}).filter(p=>!p.photos.length));async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!visitor.value)return;busy.value=true;try{const slot=`content.library-${crypto.randomUUID()}.asset`,response=await fetch(`/api/admin/visitor-content/visual-media/${encodeURIComponent(slot)}`,{method:'POST',body:file,headers:{'Content-Type':file.type,'X-Media-Version':String(visitor.value.state.media.version),'X-Original-Name':encodeURIComponent(file.name)}});const result=await response.json();if(!response.ok)throw new Error(result.error);message.value=`已上传 ${file.name}。可在地点编辑页关联为封面或图集。`;await load()}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
</script><template><div v-if="studio&&visitor" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">照片与媒体</p><h1>媒体库</h1><p>手机可以直接拍照或从相册选择。上传后的原文件按内容哈希保存，不会同名覆盖。</p></div><label class="button primary-action camera-upload">{{busy?'上传中…':'拍照或上传'}}<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" @change="upload"></label></div><p v-if="message" class="inline-message">{{message}}</p><section><h2>当前图片</h2><div class="media-library-grid"><article v-for="(image,slot) in visitor.state.media.items" :key="slot"><img :src="`/api/admin/visitor-content/media/${image.fileName}`"><strong>{{slot}}</strong><small>{{image.originalName}}</small></article><p v-if="!Object.keys(visitor.state.media.items).length">媒体库目前为空。</p></div></section><section><h2>缺少图片的地点（{{missing.length}}）</h2><div class="need-list"><RouterLink v-for="p in missing" :to="`/studio/places/${p.id}`">{{p.name.zh}} <small>{{p.id}}</small></RouterLink></div></section></div></template>
